targets.rawSql:
select step, ms from (
  select 1 as n, 'Camera starts' as step, round(percentile_cont(0.5) within group (order by (measures->>'camera_start_to_first_frame_ms')::numeric)) as ms
    from telemetry_events where name = 'scan' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
  union all select 2, 'Code read → payment accepted', round(percentile_cont(0.5) within group (order by (measures->>'qr_to_admitted_ms')::numeric))
    from telemetry_events where name = 'payment' and dimensions->>'wallet' = '$wallet' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
  union all select 3, 'Wallet prepares', round(percentile_cont(0.5) within group (order by (measures->>'admitted_to_prepared_ms')::numeric))
    from telemetry_events where name = 'payment' and dimensions->>'wallet' = '$wallet' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
  union all select 4, 'Wallet pays', round(percentile_cont(0.5) within group (order by (measures->>'submit_to_outcome_ms')::numeric))
    from telemetry_events where name = 'payment' and dimensions->>'outcome' = 'paid' and dimensions->>'wallet' = '$wallet' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
) steps where ms is not null order by n

select replace(dimensions->>'error', '_', ' ') as problem, count(*) as times
from telemetry_events where name = 'payment' and dimensions->>'error' <> 'none' and dimensions->>'wallet' = '$wallet' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1 order by 2 desc
